(() => {
'use strict';
const canvas=document.getElementById('view'), ctx=canvas.getContext('2d',{alpha:false}), mini=document.getElementById('minimap'), mctx=mini.getContext('2d');
const W=384,H=216,FOV=Math.PI/3, TAU=Math.PI*2;
const maps=[
 ['################','#..............#','#....#.........#','#....#..##.....#','#..........#...#','#...##.........#','#..............#','#..#......#....#','#..............#','#....#.........#','#..............#','################'],
 ['################','#..............#','#..##...........#','#...............#','#.....#.........#','#.....#..##.....#','#...............#','#..#............#','#..#......#.....#','#...............#','#..............X#','################'],
 ['################','#..............#','#..##...........#','#...............#','#.....#.........#','#...............#','#..#......#.....#','#...............#','#......##.......#','#...............#','#..............X#','################']
];
const stages=[
 {name:'THE ASHEN GALLERY',theme:{wall:'#584333',mortar:'#302720',floor:'#302a23',ceiling:'#181412',torch:'#e39a4e'},spawn:[2.5,1.5],stairs:[13.5,10.4],people:[['Mira the Scout','SCOUT · LOST DELVER',3.6,3.5,'scout'],['Bram the Smith','BLACKSMITH',2.4,7.5,'smith'],['Tallow','WANDERING MERCHANT',8.5,2.5,'merchant']],enemies:[['orc',8.5,5.5],['bat',11.5,8.5],['orc',6.5,9.5]],ore:[10.5,4.5]},
 {name:'THE SUNKEN CHAPEL',theme:{wall:'#43504a',mortar:'#252d2a',floor:'#292f2d',ceiling:'#141a19',torch:'#80c2a3'},spawn:[1.5,1.5],stairs:[14.4,10.4],people:[['Sister Ysolde','KEEPER OF THE LANTERN',4.5,2.5,'priest'],['Tallow','WANDERING MERCHANT',2.5,8.5,'merchant']],enemies:[['orc',7.5,4.5],['bat',11.5,6.5],['orc',5.5,9.5],['orc',12.5,9.5]],ore:[10.5,3.5]},
 {name:'THE IRON ROOTS',theme:{wall:'#554037',mortar:'#32231e',floor:'#2d2521',ceiling:'#17100f',torch:'#e18c5a'},spawn:[1.5,1.5],stairs:[14.4,10.4],people:[['Mara','YOUR BELOVED',12.5,2.5,'wife']],enemies:[['orc',6.5,4.5],['orc',10.5,5.5],['orc',4.5,9.5],['boss',12.5,8.5]],ore:null}
];
const state={running:false,stage:0,x:2.5,y:1.5,angle:0,health:100,maxHealth:100,gold:12,xp:0,kills:0,levelKills:0,damage:24,weapon:'Worn iron sword',weaponDetail:'A promise is sharper than steel.',attackAt:0,fireAt:0,guardUntil:0,healAt:0,invulnUntil:0,lastTime:0,dialog:null,dialogOpen:false,quest:false,questDone:false,ore:false,skill:{fire:false,guard:false,heal:false},enemies:[],npcs:[],particles:[],pickup:null,won:false,muted:false};
let held={}, zbuffer=new Float32Array(W), worldTime=0, toastTimer=0, pointerLocked=false, lookTouch=null;
const $=s=>document.querySelector(s), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function resize(){const dpr=Math.min(1.5,devicePixelRatio||1);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.imageSmoothingEnabled=false}addEventListener('resize',resize);resize();
function tile(x,y){const m=maps[state.stage];if(!m||x<0||y<0||y>=m.length||x>=m[0].length)return '#';return m[y][x]}
function solid(x,y){return tile(Math.floor(x),Math.floor(y))==='#'}
function setupStage(i){state.stage=i;state.levelKills=0;state.ore=false;const s=stages[i];state.x=s.spawn[0];state.y=s.spawn[1];state.angle=0;state.npcs=s.people.map(p=>({name:p[0],role:p[1],x:p[2],y:p[3],type:p[4]}));state.enemies=s.enemies.map((e,j)=>({type:e[0],x:e[1],y:e[2],hp:e[0]==='boss'?170:e[0]==='orc'?55:28,max:e[0]==='boss'?170:e[0]==='orc'?55:28,damage:e[0]==='boss'?19:e[0]==='orc'?12:7,speed:e[0]==='bat'?.85:.48,attack:0,hit:0,phase:Math.random()*5,alive:true,id:j}));state.pickup=s.ore?{x:s.ore[0],y:s.ore[1],got:false,type:'ore'}:null;$('#levelName').textContent=s.name;$('#floorLabel').textContent=`DEPTH 0${i+1}`;$('#journalText').textContent=i===0?'The trail runs down. Keep your blade ready.':i===1?'A cold bell rings below the waterline.':'You hear Mara. Nothing else matters.';updateUI();toast(i===2?'The Iron Roots. She is close.':`You descend to ${s.name.toLowerCase()}.`);}
function audio(freq=210,duration=.08,type='sine',vol=.025){if(state.muted)return;try{const ac=audio.ac||(audio.ac=new (AudioContext||webkitAudioContext)()),o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch{}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function updateUI(){ $('#healthBar').style.width=`${100*state.health/state.maxHealth}%`;$('#healthText').textContent=Math.ceil(state.health);$('#goldText').textContent=state.gold;$('#xpBar').style.width=`${Math.min(100,state.xp/2)}%`;$('#weaponName').textContent=state.weapon;$('#weaponDetail').textContent=state.weaponDetail;let n=state.levelKills;$('#progressText').textContent=state.stage<2?`THE ORC TRAIL · ${Math.min(n,3)} / 3`:state.won?'MARA IS SAFE':'FIND MARA · THE IRON ROOTS';$('#progressBar').style.width=state.stage<2?`${Math.min(100,n/3*100)}%`:'100%';$('#objective').textContent=state.stage===2?'Find Mara. Bring her home.':state.stage===1?'Follow the trail through the Sunken Chapel.':'Find a way deeper. Bring Mara home.';document.querySelector('[data-skill="1"]').style.opacity=state.skill.fire?'1':'.45';document.querySelector('[data-skill="2"]').style.opacity=state.skill.guard?'1':'.45';document.querySelector('[data-skill="3"]').style.opacity=state.skill.heal?'1':'.45';}
function start(){ $('#menu').style.display='none';state.running=true;setupStage(0);state.lastTime=performance.now();requestAnimationFrame(loop);canvas.requestPointerLock?.();}
$('#startBtn').addEventListener('click',start);$('#againBtn').addEventListener('click',()=>location.reload());$('#soundBtn').addEventListener('click',()=>{state.muted=!state.muted;$('#soundBtn').textContent=state.muted?'♫̸':'♫';toast(state.muted?'Sound off':'Sound on')});
document.addEventListener('pointerlockchange',()=>pointerLocked=document.pointerLockElement===canvas);document.addEventListener('mousemove',e=>{if(pointerLocked&&state.running&&!state.dialogOpen)state.angle+=e.movementX*.0022});canvas.addEventListener('click',()=>{if(state.running&&!state.dialogOpen)canvas.requestPointerLock?.()});
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();held[k]=true;if(k==='e')interact();if(k===' ')attack();if(k==='1')cast('fire');if(k==='2')cast('guard');if(k==='3')cast('heal');if(k==='escape'&&state.dialogOpen)closeDialogue()});addEventListener('keyup',e=>held[e.key.toLowerCase()]=false);
let dragX=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'){dragX=e.clientX;canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointermove',e=>{if(dragX!==null){state.angle+=(e.clientX-dragX)*.006;dragX=e.clientX}});canvas.addEventListener('pointerup',()=>dragX=null);
document.querySelectorAll('[data-move]').forEach(b=>{const key={forward:'w',back:'s',left:'a',right:'d'}[b.dataset.move];b.addEventListener('pointerdown',e=>{e.preventDefault();held[key]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>held[key]=false))});$('#touchUse').addEventListener('click',interact);$('#touchAttack').addEventListener('click',attack);document.querySelectorAll('.skill').forEach(b=>b.addEventListener('click',()=>cast(({1:'fire',2:'guard',3:'heal'})[b.dataset.skill])));
function loop(now){if(!state.running)return;const dt=Math.min(.05,(now-state.lastTime)/1000||0);state.lastTime=now;worldTime+=dt;if(!state.dialogOpen){move(dt);updateEnemies(dt);updateParticles(dt)}render();requestAnimationFrame(loop)}
function move(dt){let f=(held.w||held.arrowup?1:0)-(held.s||held.arrowdown?1:0),side=(held.d||held.arrowright?1:0)-(held.a||held.arrowleft?1:0);if(!f&&!side)return;let speed=2.15*dt;if(held.shift)speed*=1.35;const mag=Math.hypot(f,side);f/=mag;side/=mag;const nx=state.x+(Math.cos(state.angle)*f+Math.cos(state.angle+Math.PI/2)*side)*speed,ny=state.y+(Math.sin(state.angle)*f+Math.sin(state.angle+Math.PI/2)*side)*speed;if(!solid(nx+.18*Math.sign(nx-state.x),state.y))state.x=nx;if(!solid(state.x,ny+.18*Math.sign(ny-state.y)))state.y=ny;if(tile(Math.floor(state.x),Math.floor(state.y))==='X')nextStage();if(state.pickup&&!state.pickup.got&&dist(state.x,state.y,state.pickup.x,state.pickup.y)<.48){state.pickup.got=true;state.ore=true;toast('Cinder-ore gathered · a smith may want this');audio(660,.16,'triangle');}if(state.stage===2&&state.won===false&&dist(state.x,state.y,12.5,2.5)<.65&&state.enemies.some(e=>e.alive&&e.type==='boss')===false)rescue();}
function dist(x,y,a,b){return Math.hypot(x-a,y-b)}
function nextStage(){if(state.stage<2){setupStage(state.stage+1);audio(380,.2,'triangle')}else rescue()}
function updateEnemies(dt){for(const e of state.enemies){if(!e.alive)continue;e.phase+=dt*4;if(e.hit>0)e.hit-=dt;const d=dist(state.x,state.y,e.x,e.y);if(d<.58){if(worldTime>e.attack){e.attack=worldTime+1.15;damagePlayer(e.damage);continue}}else if(d<8){const dx=(state.x-e.x)/d,dy=(state.y-e.y)/d,step=e.speed*dt;if(!solid(e.x+dx*step,e.y))e.x+=dx*step;if(!solid(e.x,e.y+dy*step))e.y+=dy*step}}}
function damagePlayer(n){if(worldTime<state.invulnUntil)return;state.invulnUntil=worldTime+.55;state.health=Math.max(0,state.health-n);$('#hurtFlash').style.opacity='.8';setTimeout(()=>$('#hurtFlash').style.opacity='0',150);audio(95,.22,'sawtooth',.045);updateUI();if(state.health<=0){state.health=50;state.gold=Math.max(0,state.gold-5);state.x=stages[state.stage].spawn[0];state.y=stages[state.stage].spawn[1];toast('The dark spits you back out. You lose 5 ✦.');updateUI()}}
function attack(){if(!state.running||state.dialogOpen||worldTime<state.attackAt)return;state.attackAt=worldTime+.46;audio(150,.12,'triangle',.04);const aim=state.angle;let target=null,best=1.65;for(const e of state.enemies){if(!e.alive)continue;const d=dist(state.x,state.y,e.x,e.y),a=Math.atan2(e.y-state.y,e.x-state.x),delta=Math.atan2(Math.sin(a-aim),Math.cos(a-aim));if(Math.abs(delta)<.42&&d<best&&!lineBlocked(state.x,state.y,e.x,e.y)){best=d;target=e}}if(target){target.hp-=state.damage;target.hit=.18;particles(target.x,target.y,'#ffc06b');audio(90,.1,'square',.04);if(target.hp<=0){target.alive=false;state.gold+=target.type==='boss'?18:target.type==='orc'?4:2;state.xp+=target.type==='boss'?65:20;state.kills++;state.levelKills++;toast(target.type==='boss'?'The orc captain falls.':'A creature falls into the dust.');updateUI();if(target.type==='boss'){setTimeout(rescue,550)}}}}
function lineBlocked(x,y,a,b){let n=Math.ceil(dist(x,y,a,b)*12);for(let i=1;i<n;i++){let t=i/n;if(solid(x+(a-x)*t,y+(b-y)*t))return true}return false}
function cast(type){if(!state.running||state.dialogOpen)return;if(type==='fire'){if(!state.skill.fire){toast('The trainer may teach you Ember bolt.');return}if(worldTime<state.fireAt)return;state.fireAt=worldTime+2.2;let target=null,best=7;for(const e of state.enemies){if(!e.alive)continue;let d=dist(state.x,state.y,e.x,e.y),a=Math.atan2(e.y-state.y,e.x-state.x),delta=Math.atan2(Math.sin(a-state.angle),Math.cos(a-state.angle));if(d<best&&Math.abs(delta)<.22&&!lineBlocked(state.x,state.y,e.x,e.y)){best=d;target=e}}if(target){target.hp-=38;target.hit=.2;particles(target.x,target.y,'#ffb35a');toast('Ember bolt · 38 damage');if(target.hp<=0){target.alive=false;state.gold+=4;state.xp+=20;state.levelKills++;updateUI()}}else toast('The ember fades into the dark.');audio(440,.3,'sawtooth',.035)}else if(type==='guard'){if(!state.skill.guard){toast('Find the chapel keeper to learn Iron Guard.');return}if(worldTime<state.guardUntil)return;state.guardUntil=worldTime+6;state.invulnUntil=worldTime+2.4;toast('Iron Guard · you are protected');audio(280,.25,'triangle')}else{if(!state.skill.heal){toast('The chapel keeper can teach you Mending Light.');return}if(worldTime<state.healAt)return;if(state.health>=state.maxHealth){toast('You are already whole.');return}state.healAt=worldTime+10;state.health=Math.min(state.maxHealth,state.health+36);toast('Mending Light · +36 vitality');audio(620,.35,'sine');updateUI()}}
function particles(x,y,color){for(let i=0;i<8;i++)state.particles.push({x,y,vx:(Math.random()-.5)*2,vy:(Math.random()-.5)*2,t:.35,color})}
function updateParticles(dt){state.particles=state.particles.filter(p=>p.t>0);for(const p of state.particles){p.t-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt}}

