function updateParticles(dt){state.particles=state.particles.filter(p=>p.t>0);for(const p of state.particles){p.t-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt}}
function nearestThing(){let found=null,best=1.5;for(const n of state.npcs){const d=dist(state.x,state.y,n.x,n.y);if(d<best&&!lineBlocked(state.x,state.y,n.x,n.y)){best=d;found={...n,kind:'npc',d}}}for(const e of state.enemies){if(!e.alive)continue;const d=dist(state.x,state.y,e.x,e.y);if(d<best&&!lineBlocked(state.x,state.y,e.x,e.y)){best=d;found={...e,kind:'enemy',d}}}if(tile(Math.floor(state.x+Math.cos(state.angle)*.85),Math.floor(state.y+Math.sin(state.angle)*.85))==='X')found={kind:'stairs',d:.8};return found}
function interact(){if(!state.running)return;if(state.dialogOpen){closeDialogue();return}const target=nearestThing();if(!target){toast('Nothing here but stone and silence.');return}if(target.kind==='stairs'){nextStage();return}if(target.kind==='enemy'){attack();return}talk(target)}
function talk(n){state.dialogOpen=true;state.dialog=n;const cfg={scout:['Mira the Scout','LOST DELVER','An orc patrol dragged a cage down toward the chapel. Three of them guard the lower passage. Keep your eyes on their shields.','Mira grips your forearm. “Your wife? I saw them take her. Go. I’ll find the others.”'],smith:['Bram the Smith','BLACKSMITH','A blade can be made to remember. I can temper yours with cinder-ore—or sell you a better edge.','Bram lays a hammer aside. “Ore makes a fine edge. Bring me the ember-glass from these caves.”'],merchant:['Tallow','WANDERING MERCHANT','I trade in things that keep a person breathing. A flask of red tonic costs 8 ember coins.','Tallow opens a little leather roll. “No credit in the underworld, friend.”'],priest:['Sister Ysolde','KEEPER OF THE LANTERN','The chapel remembers its old protections. I can teach you Ember Bolt for 10 coins, Iron Guard for 8, or Mending Light for 8.','“The dark is not empty,” she whispers. “But neither are you.”'],wife:['Mara','YOUR BELOVED','You came all this way. I knew you would. The captain has the key—did you find him?','Mara reaches for your hand. “Let’s go home.”']};let [name,role,intro,second]=cfg[n.type]||['Survivor','DELVER','Please, help me.',''];$('#speakerName').textContent=name;$('#speakerRole').textContent=role;$('#dialoguePortrait').textContent=({scout:'⚒',smith:'⚒',merchant:'♙',priest:'✧',wife:'♥'})[n.type]||'?';$('#dialogueText').textContent=intro;const opts=$('#dialogueOptions');opts.innerHTML='';const add=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;opts.appendChild(b)};if(n.type==='scout'){add(state.quest?'Ask about the trail':'Ask about my wife',()=>{if(!state.quest){state.quest=true;state.gold+=5;$('#dialogueText').textContent=second+' She presses five coins into your hand. “For the road.”';toast('Scout’s clue · +5 ember coins');updateUI()}else $('#dialogueText').textContent=second})}if(n.type==='smith'){add('Temper blade · 10 ✦',()=>{if(state.weapon==='Cinder-tempered blade'){say('Your blade is already tempered.');return}if(state.gold<10){say('“Come back with ten coins.”');return}state.gold-=10;state.damage=38;state.weapon='Cinder-tempered blade';state.weaponDetail='A bright edge, warm as a hearth.';say('Bram taps the new edge. “Now let it sing.”');updateUI()});if(state.ore)add('Trade cinder-ore · +12 ✦',()=>{if(!state.ore){say('You have no cinder-ore.');return}state.ore=false;state.gold+=12;say('“Good ore. Fair trade.” +12 ember coins.');updateUI()})}if(n.type==='merchant')add('Buy red tonic · 8 ✦',()=>{if(state.gold<8){say('“Your purse is too light.”');return}if(state.health===state.maxHealth){say('“You’re already hale. Save your coin.”');return}state.gold-=8;state.health=Math.min(state.maxHealth,state.health+45);say('The tonic burns like cinnamon. +45 vitality.');updateUI()});if(n.type==='priest'){const lessons=[['Learn Ember Bolt · 10 ✦','fire',10],['Learn Iron Guard · 8 ✦','guard',8],['Learn Mending Light · 8 ✦','heal',8]];for(const [label,key,cost] of lessons)add(state.skill[key]?`Learned: ${key==='fire'?'Ember Bolt':key==='guard'?'Iron Guard':'Mending Light'}`:label,()=>{if(state.skill[key]){say('The lesson is already yours.');return}if(state.gold<cost){say('“A lesson takes time, and time is dear.”');return}state.gold-=cost;state.skill[key]=true;say(`${key==='fire'?'Ember Bolt':key==='guard'?'Iron Guard':'Mending Light'} learned. Use key ${key==='fire'?1:key==='guard'?2:3}.`);updateUI()})}if(n.type==='wife')add('Take Mara’s hand',()=>rescue());add('Leave',closeDialogue);$('#dialogue').classList.remove('hidden')}
function say(text){$('#dialogueText').textContent=text}
function closeDialogue(){state.dialogOpen=false;state.dialog=null;$('#dialogue').classList.add('hidden')}
function rescue(){if(state.won)return;if(state.enemies.some(e=>e.alive&&e.type==='boss')){toast('The orc captain still bars the way.');return}state.won=true;state.running=false;closeDialogue();$('#endingTitle').textContent='Home, at last.';$('#endingText').textContent='You crossed three depths of stone and shadow. Mara takes your hand, and together you follow the old road back toward the first light. The underworld keeps its secrets—but not this one.';$('#ending').classList.remove('hidden');audio(660,.6,'sine',.04)}
function render(){g.clearRect(0,0,W,H);const s=stages[state.stage].theme;const sky=g.createLinearGradient(0,0,0,H/2);sky.addColorStop(0,s.ceiling);sky.addColorStop(1,'#231b15');g.fillStyle=sky;g.fillRect(0,0,W,H/2);const floor=g.createLinearGradient(0,H/2,0,H);floor.addColorStop(0,s.floor);floor.addColorStop(1,'#0e0c0b');g.fillStyle=floor;g.fillRect(0,H/2,W,H/2);
 // perspective floor seams
 for(let y=H/2+3;y<H;y+=Math.max(3,Math.floor((y-H/2)/10))){const alpha=Math.min(.18,(y-H/2)/H*.22);g.fillStyle=`rgba(190,145,92,${alpha})`;g.fillRect(0,y,W,1)}
 const playerAngle=state.angle;for(let x=0;x<W;x++){const rayAngle=playerAngle+(x/W-.5)*FOV,rx=Math.cos(rayAngle),ry=Math.sin(rayAngle);let mapX=Math.floor(state.x),mapY=Math.floor(state.y),deltaX=Math.abs(1/(rx||.00001)),deltaY=Math.abs(1/(ry||.00001)),stepX=rx<0?-1:1,stepY=ry<0?-1:1,sideX=(rx<0?state.x-mapX:mapX+1-state.x)*deltaX,sideY=(ry<0?state.y-mapY:mapY+1-state.y)*deltaY,side=0,hit=false,steps=0;while(!hit&&steps++<40){if(sideX<sideY){sideX+=deltaX;mapX+=stepX;side=0}else{sideY+=deltaY;mapY+=stepY;side=1}if(tile(mapX,mapY)==='#')hit=true}let d=side===0?sideX-deltaX:sideY-deltaY;d=Math.max(.08,d*Math.cos(rayAngle-playerAngle));zbuffer[x]=d;const wh=Math.min(H*2,H/d),top=Math.floor((H-wh)/2),wallX=side===0?state.y+d*ry:state.x+d*rx;let texture=Math.floor((wallX-Math.floor(wallX))*8),brick=(Math.floor(wallX*2)+Math.floor(d*2))%2===0;let shade=clamp(1-d/10,.18,.88)*(side===1?.72:1)*(brick?.87:1);g.fillStyle=shadeColor(s.wall,shade);g.fillRect(x,top,1,wh);let mortar=(texture===0||texture===7||((Math.floor((H/2-top)/17)+(Math.floor(wallX*2)%2))%2===0&&texture===4));if(mortar){g.fillStyle=shadeColor(s.mortar,shade);g.fillRect(x,top+Math.floor(wh*.48),1,1)}if(d<4.2&&texture===2&&x%2===0){g.fillStyle=`rgba(${s.torch==='#e39a4e'?'235,150,72':s.torch==='#80c2a3'?'105,201,158':'232,130,80'},${.08*(1+Math.sin(worldTime*3+x)*.2)})`;g.fillRect(x,top,1,wh)}}
 // draw billboard creatures, props and people sorted far-to-near
 const list=[];for(const e of state.enemies)if(e.alive)list.push({...e,kind:'enemy'});for(const n of state.npcs)list.push({...n,kind:'npc'});if(state.pickup&&!state.pickup.got)list.push({...state.pickup,kind:'pickup'});list.sort((a,b)=>dist(state.x,state.y,b.x,b.y)-dist(state.x,state.y,a.x,a.y));for(const ent of list)drawBillboard(ent);
 drawWeapon();drawCrosshair();drawMinimap();const prompt=nearestThing();$('#interaction').classList.toggle('visible',!!prompt&&!state.dialogOpen);if(prompt)$('#interactionText').textContent=prompt.kind==='stairs'?'Descend to the next depth':prompt.kind==='enemy'?'Strike':prompt.name;const vctx=ctx;vctx.imageSmoothingEnabled=false;vctx.clearRect(0,0,canvas.width,canvas.height);vctx.drawImage(scene,0,0,canvas.width,canvas.height);}
function shadeColor(hex,k){const v=parseInt(hex.slice(1),16),r=Math.floor((v>>16)*k),g=Math.floor(((v>>8)&255)*k),b=Math.floor((v&255)*k);return `rgb(${r},${g},${b})`}

