t;if(held.shift)speed*=1.35;const mag=Math.hypot(f,side);f/=mag;side/=mag;const nx=state.x+(Math.cos(state.angle)*f+Math.cos(state.angle+Math.PI/2)*side)*speed,ny=state.y+(Math.sin
