ull,best=1.65;for(const e of state.enemies){if(!e.alive)continue;const d=dist(state.x,state.y,e.x,e.y),a=Math.atan2(e.y-state.y,e.x-state.x),delta=Math.atan2(Math.sin(a-aim),Math.c
