=38;target.hit=.2;particles(target.x,target.y,'#ffb35a');toast('Ember bolt · 38 damage');if(target.hp<=0){target.alive=false;state.gold+=4;state.xp+=20;state.levelKills++;updateUI(
)}}else toast('The ember fades into the dark.');audio(440,.3,'sawtooth',.035)}else if(type==='guard'){if(!state.skill.guard){toast('Find the chapel keeper to learn Iron Guard.');re
